        /** Per frame: the firefighter's hose. */
        public static void tick(World w, Person p, float dt) {
            if (p.kind == Person.FIREFIGHTER && p.aim && p.target != null && p.target.burning && p.able && armsWork(p)) {
                float s = p.scale;
                float hx = wristX(p), hy = wristY(p);
                float ax = armDirX(p), ay = armDirY(p);
                int n = (int) (60f * dt + w.rnd.nextFloat());
                for (int k = 0; k < n; k++) {
                    float sp = 620f + w.fx.rf() * 160f;
                    w.fx.water(hx, hy, ax * sp + w.fx.rr_(50), ay * sp - 90f + w.fx.rr_(50));
                }
                float reach = 320f * s;
                for (int i = 0; i < w.ents.size(); i++) {
                    Ent o = w.ents.get(i);
                    if (!o.burning) continue;
                    float rx = o.cx() - hx, ry = o.cy() - hy;
                    float t = Math.max(0f, Math.min(reach, rx * ax + ry * ay));
                    float ex = rx - ax * t, ey = ry - ay * t, rr = o.radius() + 34f;
                    if (ex * ex + ey * ey > rr * rr) continue;
                    o.burnT -= dt * 12f;
                    if (w.rnd.nextFloat() < dt * 12f) w.fx.smoke(o.cx() + w.fx.rr_(o.radius()), o.cy() - 10f, 8f, unchecked((int)0xFFd8dde3U));
                    if (o is Prop && ((Prop) o).explosive && ((Prop) o).fuse > 0f && ((Prop) o).type != Items.GRENADE && ((Prop) o).type != Items.DYNAMITE) ((Prop) o).fuse = -1f;
                    if (o.burnT <= 0.5f) { o.burning = false; o.burnT = 0f; w.stats.fires++; }
                }
            }
        }

        // ----------------------------------------------------------------------------- machines ------

        private static float wrap(float a) {
            while (a > Math.PI) a -= 2f * (float) Math.PI;
            while (a < -Math.PI) a += 2f * (float) Math.PI;
            return a;
        }

        /** Every physics step. */
        public static void machineStep(World w, Prop m, float dt) {
            RB b = m.main();
            switch (m.type) {
                case Items.THRUSTER:
                    if (m.thrust) {
                        float ux = (float) Math.sin(b.a), uy = (float) -Math.cos(b.a);
                        float along = b.vx * ux + b.vy * uy;
                        if (along < 1500f) { b.fx += ux * 3.0e7f; b.fy += uy * 3.0e7f; }
                    }
                    break;
                case Items.DRONE: {
                    if (m.dead || !m.on) { b.gravScale = 1f; break; }
                    b.gravScale = 1f;
                    float ax = clampF(9f * (m.goalX - b.x) - 4.5f * b.vx, -1400f, 1400f);
                    float ay = clampF(14f * (m.goalY - b.y) - 6f * b.vy - w.sim.gravity, -5200f, 5200f);
                    b.fx += b.m * ax; b.fy += b.m * ay;
                    float tilt = clampF(ax * 0.0002f, -0.25f, 0.25f);
                    float tq = -70f * (b.a - tilt) - 12f * b.w;
                    b.tq += b.I * tq;
                    break;
                }
                case Items.TURRET:
                    if (m.aimJoint != null && !m.dead) {
                        Joint j = m.aimJoint;
                        m.aimJoint.muscle = m.on;
                        float want = m.aimA - j.a.a - j.ref_;
                        float cur = j.angle();
                        while (want - cur > Math.PI) want -= 2f * (float) Math.PI;
                        while (want - cur < -Math.PI) want += 2f * (float) Math.PI;
                        // integral trim removes the small sag of the soft muscle
                        float err = wrap(m.aimA - m.barrel.a);
                        m.trim = clampF(m.trim + err * 3f * dt, -0.4f, 0.4f);
                        j.target = want + m.trim;
                        j.limit = false;
                    }
                    break;
                default: break;
            }
        }

        private static float clampF(float v, float lo, float hi) { return v < lo ? lo : (v > hi ? hi : v); }

        /** Every frame: look for hostiles and shoot. */
        public static void machineThink(World w, Prop m, float dt) {
            if (m.shotCd > 0f) m.shotCd -= dt;
            if (m.reloadT > 0f) { m.reloadT -= dt; if (m.reloadT <= 0f) m.ammo = 12; }
            if (m.dead) {
                if (w.rnd.nextFloat() < dt * 6f) w.fx.smoke(m.cx(), m.cy() - 6f, 7f, unchecked((int)0xFF3c3c3cU));
                return;
            }
            if (!m.on) { m.target = null; m.mood = "Apagado"; return; }
            m.thinkT -= dt;
            if (m.type == Items.TURRET) turret(w, m, dt);
            else drone(w, m, dt);
        }

        private static void turret(World w, Prop m, float dt) {
            RB gun = m.barrel;
            if (gun == null) return;
            float gx = gun.x, gy = gun.y;
            if (m.thinkT <= 0f) {
                m.thinkT = 0.2f;
                Person nt = nearestHostile(w, gx, gy, 1500f, null);
                if (nt != null) {
                    float ndx = nt.rb[Person.CHEST].x - gx, ndy = nt.rb[Person.CHEST].y - gy, d = (float) Math.hypot(ndx, ndy);
                    JList<Sim.Hit> hs = w.sim.ray(gx + ndx / d * 40f, gy + ndy / d * 40f, ndx / d, ndy / d, d);
                    bool clear = true;
                    for (int i = 0; i < hs.size(); i++) {
                        Object u = hs.get(i).shape.body.user;
                        if (u == m) continue;
                        if (u is Person) { clear = ((Person) u).hostile() || ((Person) u).dead; break; }
                        if (u is Prop && (((Prop) u).machine() || ((Prop) u).type == Items.PLATFORM)) { clear = false; break; }
                    }
                    m.target = clear ? nt : null;
                } else m.target = null;
            }
            Ent t = m.target;
            if (t != null && (t.removed || (t is Person && !((Person) t).hostile()))) t = m.target = null;
            if (t == null) {
                m.work += dt;
                m.aimA = (m.homeDir() > 0 ? 0f : (float) Math.PI) + (float) Math.sin(m.work * 0.8f) * 0.7f * (m.homeDir() > 0 ? -1f : 1f) - 0.15f;
                m.mood = "Vigilando";
                return;
            }
            float pvx = m.aimJoint != null ? m.aimJoint.anchorAX() : gx, pvy = m.aimJoint != null ? m.aimJoint.anchorAY() : gy;
            float dx = cxOf(t) - pvx, dy = cyOf(t) - pvy;
            m.aimA = (float) Math.atan2(dy, dx);
            m.mood = "Objetivo fijado";
            float cur = gun.a;
            float diff = Math.abs(wrap(cur - m.aimA));
            if (diff > 0.02f || m.shotCd > 0f || m.reloadT > 0f) return;
            float bx = (float) Math.cos(cur), by = (float) Math.sin(cur);
            w.shoot(m, gx + bx * 30f, gy + by * 30f, bx, by, 16f, 520f, 1);
            if (w.sfx != null) w.sfx.shot();
            gun.applyImpulse(-bx * 1.2e5f, -by * 1.2e5f, gun.x, gun.y);
            m.shotCd = 0.13f;
            if (--m.ammo <= 0) { m.reloadT = 0.9f; m.mood = "Recargando"; }
        }

        private static void drone(World w, Prop m, float dt) {
            RB b = m.main();
            if (m.thinkT <= 0f) { m.thinkT = 0.25f; m.target = nearestHostile(w, b.x, b.y, 1700f, null); }
            Ent t = m.target;
            if (t != null && (t.removed || (t is Person && !((Person) t).hostile()))) t = m.target = null;
            if (t == null) {
                m.work += dt;
                m.goalX = m.homeX + (float) Math.sin(m.work * 0.45f) * 220f;
                m.goalY = w.sim.floorY - 330f + (float) Math.sin(m.work * 1.3f) * 25f;
                m.mood = "Patrullando";
            } else {
                float tx = cxOf(t), ty = cyOf(t);
                float side = b.x < tx ? -1f : 1f;
                m.goalX = tx + side * 240f;
                m.goalY = ty - 200f;
                m.mood = "Atacando";
                float dx = tx - b.x, dy = ty - b.y, l = (float) Math.sqrt(dx * dx + dy * dy);
                if (l > 1f && l < 900f && m.shotCd <= 0f && m.reloadT <= 0f) {
                    float ax = dx / l, ay = dy / l;
                    JList<Sim.Hit> hs = w.sim.ray(b.x + ax * 20f, b.y + 10f + ay * 20f, ax, ay, l);
                    bool clear = true;
                    for (int i = 0; i < hs.size(); i++) {
                        Object u = hs.get(i).shape.body.user;
                        if (u == m) continue;
                        if (u is Person) { clear = ((Person) u).hostile() || ((Person) u).dead; break; }
                        if (u is Prop && (((Prop) u).machine() || ((Prop) u).type == Items.PLATFORM)) { clear = false; break; }
                    }
                    if (clear) {
                        w.shoot(m, b.x + ax * 26f, b.y + 10f + ay * 26f, ax, ay, 12f, 380f, 1);
                        if (w.sfx != null) w.sfx.shot();
                        m.shotCd = 0.32f;
                        if (--m.ammo <= 0) m.reloadT = 1.4f;
                    }
                }
            }
            m.goalX = clampF(m.goalX, w.sim.wallL + 60f, w.sim.wallR - 60f);
            m.goalY = clampF(m.goalY, w.sim.ceilY + 70f, w.sim.floorY - 90f);
        }
    }
}
